-- Daily challenges for 2026-10-06: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-06

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('gentle-steps-after-a-loss', 'Gentle Steps After a Loss', 'For anyone living through the days and months after someone they love has died. Each day is one small, gentle way to look after yourself, honor the person, and let others help, at whatever pace grief allows.', 'Grief', 365, array['Grief', 'Loss', 'Self-Care']::text[], 1, '2026-10-06T17:00:00+00:00'::timestamptz),
  ('learning-something-new', 'Learning Something New', 'For anyone who misses the feeling of being a beginner, or keeps meaning to pick up a new skill. Each day is one small step toward learning something you are curious about, so your mind gets regular room to grow and play.', 'Creativity', 365, array['Goals', 'Motivation']::text[], 1, '2026-10-06T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('gentle-steps-after-a-loss', 'learning-something-new');

