  ('gentle-steps-after-a-loss', 16, 'Notice whether you laughed today, and let that be okay too.'),
  ('gentle-steps-after-a-loss', 17, 'Choose one task you can set down this week, and tell yourself it can wait.'),
  ('gentle-steps-after-a-loss', 18, 'Open a window for a few minutes and listen to whatever sounds come in.'),
